import{_ as a,o as t,c as e,ag as l}from"./chunks/framework.B5ULsuav.js";const c=JSON.parse('{"title":"菩提","description":"","frontmatter":{},"headers":[],"relativePath":"50-概念资料/dict-菩提.md","filePath":"50-概念资料/dict-菩提.md","lastUpdated":1778155802000}'),i={name:"50-概念资料/dict-菩提.md"};function r(u,o,d,n,h,s){return t(),e("div",null,[...o[0]||(o[0]=[l('<h1 id="菩提" tabindex="-1">菩提 <a class="header-anchor" href="#菩提" aria-label="Permalink to &quot;菩提&quot;">​</a></h1><blockquote><p>传统：佛家 | 道家对应：悟道 | 儒家对应：明德</p></blockquote><h2 id="定义" tabindex="-1">定义 <a class="header-anchor" href="#定义" aria-label="Permalink to &quot;定义&quot;">​</a></h2><p>菩提（梵语 Bodhi）意为&quot;觉悟&quot;&quot;智慧&quot;。了空居士的解释非常直白：烦恼转过来就是菩提。</p><h2 id="了空居士原话" tabindex="-1">了空居士原话 <a class="header-anchor" href="#了空居士原话" aria-label="Permalink to &quot;了空居士原话&quot;">​</a></h2><blockquote><p>&quot;烦恼即菩提——烦恼不是敌人，它是你修行的机会。每一次烦恼来的时候，就是你进步的契机。&quot;</p></blockquote><blockquote><p>&quot;一切烦恼为如来种——烦恼是觉悟的种子。&quot;</p></blockquote><blockquote><p>&quot;菩提自性，本自清净，但用此心，直了成佛。&quot;（引六祖语）</p></blockquote><h2 id="了空居士的独特诠释" tabindex="-1">了空居士的独特诠释 <a class="header-anchor" href="#了空居士的独特诠释" aria-label="Permalink to &quot;了空居士的独特诠释&quot;">​</a></h2><p>传统上菩提是&quot;觉悟&quot;的结果，了空居士更强调<strong>当下即是</strong>——不是先断尽烦恼再得菩提，而是<strong>一念转过来就是菩提</strong>。</p><blockquote><p>&quot;以无我无人无众生无寿者修一切善法，即得阿耨多罗三藐三菩提。&quot;</p></blockquote><p>这不是先修完善法再得菩提，而是<strong>你在修善法的时候，那个状态本身就是菩提</strong>。</p><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li><a href="/liaokongjushi-wisdom/50-概念资料/dict-烦恼">烦恼</a> — 烦恼转过来就是菩提</li><li><a href="/liaokongjushi-wisdom/50-概念资料/dict-涅槃">涅槃</a> — 菩提的究竟状态</li></ul><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/liaokongjushi-wisdom/10-核心模型/model-历境炼心">历境炼心</a> — 烦恼中炼出菩提</li><li><a href="/liaokongjushi-wisdom/10-核心模型/model-对法不执">对法不执</a> — 不执着&quot;我成就了菩提&quot;</li></ul><h2 id="修行实践" tabindex="-1">修行实践 <a class="header-anchor" href="#修行实践" aria-label="Permalink to &quot;修行实践&quot;">​</a></h2><ul><li>不必等到&quot;成佛&quot;才觉得有菩提</li><li>当下的一念清净、一念觉察，就是菩提</li><li>不执着于&quot;我证得了菩提&quot;的相</li></ul>',18)])])}const p=a(i,[["render",r]]);export{c as __pageData,p as default};
